document.addEventListener('DOMContentLoaded', () => {
    const vTekken = document.getElementById('bgTekken5'); // stage 1: Tekken 5 video (top)
    const vGta = document.getElementById('bgGta5');       // stage 2: GTA 5 video (stays as the background to the end of the page)
    const gtaSection = document.getElementById('gta-arena');
    const gtaCard = document.getElementById('gtaCard');
    const root = document.documentElement;
    const clamp01 = (n) => Math.min(1, Math.max(0, n));

    /* =========================================
       1. LOAD THE VIDEOS BUILT INTO THIS FILE
       (the base64 text is at the very bottom of script.js)
       ========================================= */
    function videoUrlFromBase64(b64) {
        const bin = atob(b64);
        const bytes = new Uint8Array(bin.length);
        for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
        return URL.createObjectURL(new Blob([bytes], { type: 'video/mp4' }));
    }

    vTekken.src = videoUrlFromBase64(TEKKEN5_MP4_BASE64);
    // The GTA video is prepared a moment later so the page and Tekken video start first
    setTimeout(() => {
        vGta.src = videoUrlFromBase64(GTA5_MP4_BASE64);
        vGta.load();
        render();
    }, 250);

    /* =========================================
       2. STAGE WEIGHTS (how much of each background is visible)
       weights.t + weights.g is always 1
       ========================================= */
    const weights = { t: 1, g: 0 };
    let hover = 0;          // 0 -> 1 while the mouse is over the GTA card (eased)
    let hoverTarget = 0;
    let prerollGta = false; // start the GTA video slightly before it becomes visible

    function computeWeights(y, vh) {
        // The change from the Tekken video to the GTA video starts when the GTA section's top edge
        // is 80% down the screen and finishes when it reaches 40% down the screen.
        const raw1 = (0.8 * vh - (gtaSection.offsetTop - y)) / (0.4 * vh);
        const p1 = clamp01(raw1);

        // Hovering the GTA card pulls the background to the GTA video
        const wg = p1 * (1 - hover) + hover;
        weights.t = 1 - wg;
        weights.g = wg;
        prerollGta = raw1 > -0.6 || hover > 0;
    }

    /* =========================================
       3. SOUND: AUTOPLAY, MUTE BUTTON AND AUDIO CROSSFADE
       ========================================= */
    const soundBtn = document.getElementById('soundBtn');
    const soundLabel = document.getElementById('soundLabel');
    let soundOn = false;     // true once the browser has allowed sound
    let userMuted = false;   // true only if the visitor pressed the mute button
    let unlocking = false;   // true while we are asking the browser for sound

    // Some phones (iPhone) ignore video.volume, so there we switch audio by muting instead
    const volumeAdjustable = (() => {
        try { const t = document.createElement('video'); t.volume = 0.5; return t.volume === 0.5; }
        catch (e) { return false; }
    })();

    function refreshSoundBtn() {
        soundBtn.classList.toggle('is-on', soundOn);
        soundLabel.textContent = soundOn ? 'Sound On' : 'Sound Off';
        soundBtn.setAttribute('aria-label', soundOn ? 'Mute video sound' : 'Unmute video sound');
    }

    // Runs on every animation frame: the volume of each video follows its stage weight
    function applyAudio() {
        if (unlocking) return;
        if (volumeAdjustable) {
            // equal-power curve keeps the loudness steady during the crossfade
            vTekken.volume = clamp01(Math.sqrt(weights.t));
            vGta.volume = clamp01(Math.sqrt(weights.g));
            if (vTekken.muted === soundOn) vTekken.muted = !soundOn;
            if (vGta.muted === soundOn) vGta.muted = !soundOn;
        } else {
            const mT = !soundOn || weights.t < 0.5;
            const mG = !soundOn || weights.g < 0.5;
            if (vTekken.muted !== mT) vTekken.muted = mT;
            if (vGta.muted !== mG) vGta.muted = mG;
        }
    }

    function enableSound() {
        if (userMuted || soundOn || unlocking) return;
        unlocking = true;
        const v = weights.g > weights.t ? vGta : vTekken;
        v.muted = false;
        const p = v.play();
        const done = () => { unlocking = false; soundOn = true; applyAudio(); refreshSoundBtn(); };
        const fail = () => {
            unlocking = false;
            soundOn = false;
            v.muted = true;
            const q = v.play();
            if (q && q.catch) q.catch(() => {});
            refreshSoundBtn();
        };
        if (p && p.then) { p.then(done).catch(fail); } else { done(); }
    }

    // On load: ask for sound first, fall back to muted autoplay if the browser refuses
    enableSound();

    // First click / key press / tap anywhere turns the sound on (unless they muted it)
    ['pointerdown', 'keydown', 'touchend'].forEach(evt =>
        window.addEventListener(evt, (e) => {
            if (e.target && e.target.closest && e.target.closest('#soundBtn')) return;
            enableSound();
            syncPlayback();
        })
    );

    // Mute / unmute button (top-right corner)
    soundBtn.addEventListener('click', () => {
        if (soundOn) {
            userMuted = true;
            soundOn = false;
            applyAudio();
            refreshSoundBtn();
        } else {
            userMuted = false;
            enableSound();
        }
    });
    refreshSoundBtn();

    // If a video fails to load, say so on the button instead of failing silently
    [vTekken, vGta].forEach(v => v.addEventListener('error', () => { soundLabel.textContent = 'Video error'; }));

    /* =========================================
       4. PLAY / PAUSE (only the visible videos run, to save battery)
       ========================================= */
    function setPlaying(v, need) {
        if (!v.src) return;
        if (need && v.paused) {
            const p = v.play();
            if (p && p.catch) p.catch(() => {});
        } else if (!need && !v.paused) {
            v.pause();
        }
    }

    function syncPlayback() {
        setPlaying(vTekken, weights.t > 0.002);
        setPlaying(vGta, weights.g > 0.002 || prerollGta);
    }
    vGta.addEventListener('loadeddata', syncPlayback);
    // autoplay may start a video that is not on screen yet: pause it again right away
    [vTekken, vGta].forEach(v => v.addEventListener('play', syncPlayback));

    /* =========================================
       5. SMOOTH PARALLAX + CROSSFADE ENGINE (requestAnimationFrame)
       The scroll position is eased every frame, so the background glides
       and the video, audio and image all crossfade smoothly.
       ========================================= */
    const EASE = 0.12;         // scroll smoothing: lower = floatier, higher = snappier
    const HOVER_EASE = 0.07;   // how quickly the GTA hover crossfade happens
    let targetY = window.scrollY;
    let currentY = targetY;
    let running = false;

    function setLayer(el, alpha) {
        el.style.opacity = alpha.toFixed(3);
        el.style.visibility = alpha < 0.002 ? 'hidden' : 'visible';
    }

    function render() {
        const vh = window.innerHeight;

        computeWeights(currentY, vh);
        const wt = weights.t;
        const wg = weights.g;

        // Parallax: each video rolls at its own pace while you scroll (eases to a stop, never shows an edge)
        const gtaAnchor = gtaSection.offsetTop + gtaSection.offsetHeight / 2 - vh / 2;
        const soft = (v) => 110 * Math.tanh(v / 110);
        vTekken.style.transform = `translate3d(0, ${soft(currentY * 0.16).toFixed(2)}px, 0) scale(1.06)`;
        vGta.style.transform = `translate3d(0, ${soft((currentY - gtaAnchor) * 0.12).toFixed(2)}px, 0) scale(1.06)`;

        // Picture crossfade (GTA sits on top of Tekken, so its opacity equals its weight)
        setLayer(vTekken, wt > 0.001 ? 1 : 0);
        setLayer(vGta, wg > 0.001 ? wg : 0);

        // Audio crossfade follows the same weights
        applyAudio();
        syncPlayback();
    }

    function loop() {
        const dy = targetY - currentY;
        const dh = hoverTarget - hover;
        if (Math.abs(dy) < 0.1 && Math.abs(dh) < 0.002) {
            currentY = targetY;
            hover = hoverTarget;
            render();
            running = false;   // fully caught up: stop until the next scroll or hover
            return;
        }
        currentY += dy * EASE;
        hover += dh * HOVER_EASE;
        render();
        requestAnimationFrame(loop);
    }

    function kick() {
        if (!running) {
            running = true;
            requestAnimationFrame(loop);
        }
    }

    function onScroll() {
        targetY = window.scrollY;
        kick();
    }

    window.addEventListener('scroll', onScroll, { passive: true });
    window.addEventListener('resize', onScroll);

    // Hovering the GTA card (mouse only) crossfades the background to the GTA video + audio
    if (gtaCard) {
        gtaCard.addEventListener('pointerenter', (e) => { if (e.pointerType === 'mouse') { hoverTarget = 1; kick(); } });
        gtaCard.addEventListener('pointerleave', (e) => { if (e.pointerType === 'mouse') { hoverTarget = 0; kick(); } });
        gtaCard.addEventListener('focusin', () => { hoverTarget = 1; kick(); });
        gtaCard.addEventListener('focusout', () => { hoverTarget = 0; kick(); });
    }

    render();

    /* =========================================
       4. TIC-TAC-TOE GAME
       ========================================= */
    const cells = document.querySelectorAll('.cell');
    const statusText = document.getElementById('gameStatus');
    const resetBtn = document.getElementById('resetBtn');

    let board = ["", "", "", "", "", "", "", "", ""];
    let currentPlayer = "X";
    let gameActive = true;

    const winConditions = [
        [0, 1, 2], [3, 4, 5], [6, 7, 8],
        [0, 3, 6], [1, 4, 7], [2, 5, 8],
        [0, 4, 8], [2, 4, 6]
    ];

    function updateStatus() {
        statusText.textContent = `Player ${currentPlayer}'s Turn`;
        statusText.style.color = currentPlayer === "X" ? "var(--neon-cyan)" : "var(--neon-magenta)";
        statusText.style.textShadow = `0 0 10px ${currentPlayer === "X" ? "rgba(0, 243, 255, 0.4)" : "rgba(255, 0, 234, 0.4)"}`;
    }

    function checkWin() {
        let roundWon = false;

        for (let i = 0; i < winConditions.length; i++) {
            const [a, b, c] = winConditions[i];
            if (board[a] && board[a] === board[b] && board[a] === board[c]) {
                roundWon = true;
                break;
            }
        }

        if (roundWon) {
            statusText.textContent = `PLAYER ${currentPlayer} WINS!`;
            statusText.style.color = "var(--neon-gold)";
            statusText.style.textShadow = "0 0 15px var(--neon-gold)";
            gameActive = false;
            return;
        }

        if (!board.includes("")) {
            statusText.textContent = "IT'S A DRAW!";
            statusText.style.color = "var(--text-main)";
            statusText.style.textShadow = "none";
            gameActive = false;
            return;
        }

        currentPlayer = currentPlayer === "X" ? "O" : "X";
        updateStatus();
    }

    cells.forEach(cell => {
        cell.addEventListener('click', (e) => {
            const index = e.target.getAttribute('data-index');
            if (board[index] !== "" || !gameActive) return;

            board[index] = currentPlayer;
            e.target.textContent = currentPlayer;
            e.target.classList.add(currentPlayer.toLowerCase());

            checkWin();
        });
    });

    resetBtn.addEventListener('click', () => {
        board = ["", "", "", "", "", "", "", "", ""];
        currentPlayer = "X";
        gameActive = true;

        cells.forEach(cell => {
            cell.textContent = "";
            cell.classList.remove('x', 'o');
        });

        updateStatus();
    });

    updateStatus();
});

/* ---- The two background videos (with sound), built into this file. Do not edit below this line. ---- */
const TEKKEN5_MP4_BASE64 = "";
const GTA5_MP4_BASE64 = "";